import { z } from 'zod';
import type { AgentDetail, AgentView, LlmCallView } from './agent.ts';
import type { WorldEvent } from './events.ts';
import type { WireMap } from './map.ts';
import type { WorldMeta, WorldSettings } from './world.ts';

/** World ids are generated by the server; the pattern also guards file paths. */
export const WORLD_ID_PATTERN = /^w_[a-z0-9]{8,32}$/;

/** One person in a hand-written starting cast. */
export const PersonInput = z.object({
  name: z.string().trim().min(1, 'Every person needs a name').max(40),
  familyName: z.string().trim().max(40).optional(),
  sex: z.enum(['female', 'male']),
  age: z.number().min(0).max(95),
  occupation: z.string().trim().max(60).optional(),
  traits: z.string().trim().max(400).optional(),
  background: z.string().trim().max(1500).optional(),
  /** People with the same household number share a house. */
  household: z.number().int().min(0).max(40).optional(),
  /** First name of their partner in this cast. */
  partner: z.string().trim().max(40).optional(),
  /** First names of their parents in this cast. */
  parents: z.array(z.string().trim().max(40)).max(2).optional(),
  money: z.number().int().min(0).max(100000).optional(),
});
export type PersonInput = z.infer<typeof PersonInput>;

export const CastOption = z.discriminatedUnion('mode', [
  z.object({ mode: z.literal('sample') }),
  z.object({ mode: z.literal('custom'), people: z.array(PersonInput).min(1).max(80) }),
  z.object({
    mode: z.literal('generated'),
    adults: z.number().int().min(1).max(60),
    children: z.number().int().min(0).max(60),
    /** Flesh out the generated adults with an AI (needs a provider set up). */
    useAi: z.boolean().default(false),
  }),
]);
export type CastOption = z.input<typeof CastOption>;

export const CreateWorldRequest = z.object({
  name: z.string().trim().min(1, 'Name is required').max(60),
  seed: z.string().trim().max(64).optional(),
  mapSize: z.enum(['small', 'medium', 'large']).default('medium'),
  cast: CastOption.default({ mode: 'sample' }),
});
export type CreateWorldRequest = z.input<typeof CreateWorldRequest>;

export interface WorldsResponse {
  worlds: WorldMeta[];
  activeWorldId: string | null;
}

export interface WorldResponse {
  world: WorldMeta;
}

export interface RunnerStatus {
  running: boolean;
  /** Target ticks per second (0 = as fast as possible). */
  speed: number;
  /** Measured ticks per second over the last moment. */
  actualSpeed: number;
  /** Number of agents the world is currently waiting on to decide. */
  thinking: number;
  spentUsd: number;
  capUsd: number;
  /** Paused because the spending cap was reached. */
  capReached: boolean;
}

export interface WorldViewResponse {
  meta: WorldMeta;
  settings: WorldSettings;
  map: WireMap;
  tick: number;
  runner: RunnerStatus;
  agents: AgentView[];
  /** Visible resource amounts by object id (berries on bushes, crops in fields). */
  resources: Record<string, number>;
  /** Owners' names by object id. */
  owners: Record<string, string[]>;
}

export interface MarketResponse {
  stock: Record<string, number>;
  quotes: Record<string, { buy: number; sell: number }>;
  /** Total coins held by living villagers. */
  moneySupply: number;
}

export const ControlRequest = z.object({
  running: z.boolean().optional(),
  speed: z.number().int().min(0).max(2000).optional(),
});
export type ControlRequest = z.infer<typeof ControlRequest>;

export const EventsQuery = z.object({
  limit: z.coerce.number().int().min(1).max(500).default(200),
  beforeId: z.coerce.number().int().optional(),
  agentId: z.string().max(40).optional(),
  minImportance: z.coerce.number().int().min(1).max(5).default(1),
});
export type EventsQuery = z.input<typeof EventsQuery>;

export interface EventsResponse {
  events: WorldEvent[];
}

export interface AgentResponse {
  agent: AgentDetail;
}

export interface CallsResponse {
  calls: LlmCallView[];
}

/** A person and their relatives two generations up and down, for the family tree. */
export interface FamilyNode {
  id: string;
  name: string;
  sex: 'female' | 'male';
  age: number;
  alive: boolean;
  mother?: FamilyNode | null;
  father?: FamilyNode | null;
  partner?: { id: string; name: string; alive: boolean } | null;
  children?: FamilyNode[];
}

export interface AgentsResponse {
  agents: AgentView[];
}

export interface ApiError {
  error: string;
}

/** Messages the helper pushes to the browser over the WebSocket. */
export type ServerMessage =
  | { type: 'hello'; serverVersion: string; worlds: WorldMeta[]; activeWorldId: string | null }
  | { type: 'worlds_changed'; worlds: WorldMeta[]; activeWorldId: string | null }
  | {
      type: 'frame';
      worldId: string;
      tick: number;
      runner: RunnerStatus;
      agents: AgentView[];
      /** Only resources that changed since the previous frame. */
      resources: Record<string, number>;
      /** Changes when the map changes (e.g. a house is built), so viewers reload it. */
      mapVersion: number;
    }
  | { type: 'events'; worldId: string; events: WorldEvent[] };

/** Messages the browser sends to the helper. Observer commands are added here in later phases. */
export const ClientMessage = z.discriminatedUnion('type', [z.object({ type: z.literal('ping') })]);
export type ClientMessage = z.infer<typeof ClientMessage>;
